WITH levels AS MATERIALIZED(SELECT DISTINCT id_level FROM public.personal_best_global WHERE id_user=ANY($1)), ranked AS MATERIALIZED(SELECT pb.id_user,RANK() OVER(PARTITION BY pb.id_level ORDER BY r.time) AS place,COUNT(*) OVER(PARTITION BY pb.id_level) AS field FROM public.personal_best_global pb JOIN levels USING(id_level) JOIN public.record r ON r.id=pb.id_record JOIN public."user" u ON u.id=pb.id_user WHERE NOT u.banned AND r.time>0 AND r.record_eligible), totals AS(SELECT id_user,sum(1-(place-1)::double precision/(field-1)) AS placement_sum,count(*)::integer AS eligible_level_count FROM ranked WHERE field>=20 AND id_user=ANY($1) GROUP BY id_user) INSERT INTO public.player_skill_aggregate(id_user,placement_sum,eligible_level_count,skill,date_updated) SELECT id,coalesce(t.placement_sum,0),coalesce(t.eligible_level_count,0),(5.0+coalesce(t.placement_sum,0))/(10+coalesce(t.eligible_level_count,0)),clock_timestamp() FROM unnest($1::integer[]) id LEFT JOIN totals t ON t.id_user=id ON CONFLICT(id_user) DO UPDATE SET placement_sum=excluded.placement_sum,eligible_level_count=excluded.eligible_level_count,skill=excluded.skill,date_updated=excluded.date_updated WHERE ROW(player_skill_aggregate.placement_sum,player_skill_aggregate.eligible_level_count,player_skill_aggregate.skill) IS DISTINCT FROM ROW(excluded.placement_sum,excluded.eligible_level_count,excluded.skill) RETURNING id_user AS id
